var a=59;var i=[{id:`cooking-059-01`,theoryId:59,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What happens to salt concentration as a salted sauce reduces?`,ua:`Що відбувається з концентрацією солі під час уварювання солоного соусу?`},explanation:{en:`Reducing volume concentrates nonvolatile dissolved solutes like salt.`,ua:`Зменшення об’єму концентрує нелеткі розчинені речовини, зокрема сіль.`},options:[{id:`a`,text:{en:`It usually rises because water escapes but salt largely remains`,ua:`Зазвичай зростає, бо вода випаровується, а сіль переважно залишається`}},{id:`b`,text:{en:`Salt evaporates faster than water`,ua:`Сіль випаровується швидше за воду`}},{id:`c`,text:{en:`It must become zero`,ua:`Вона обов’язково стає нульовою`}}],answer:{optionIds:[`a`]}},{id:`cooking-059-02`,theoryId:59,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Equal teaspoons of fine salt and flaky salt always weigh exactly the same.`,ua:`Однакові чайні ложки дрібної та пластівцевої солі завжди мають однакову масу.`},explanation:{en:`Crystal shape and bulk density affect volume measurements; weigh for precision.`,ua:`Форма кристалів і насипна густина впливають на об’ємне відмірювання; для точності зважуйте.`},answer:{value:!1}},{id:`cooking-059-03`,theoryId:59,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match seasoning methods with expected effects.`,ua:`Поєднайте методи соління з очікуваним ефектом.`},explanation:{en:`The timing and form of salt influence distribution and perception.`,ua:`Час і форма додавання солі впливають на розподіл та відчуття.`},leftItems:[{id:`l1`,text:{en:`Dry brining`,ua:`Сухе соління`}},{id:`l2`,text:{en:`Finishing salt`,ua:`Сіль перед подачею`}},{id:`l3`,text:{en:`Salt added before reduction`,ua:`Сіль перед уварюванням`}}],rightItems:[{id:`r3`,text:{en:`Risk of excess salinity after evaporation`,ua:`Ризик пересолення після випаровування`}},{id:`r2`,text:{en:`Localized crystals and immediate taste impact`,ua:`Окремі кристали та миттєве смакове враження`}},{id:`r1`,text:{en:`Salt works into surface over time`,ua:`Сіль поступово взаємодіє з поверхнею`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-059-04`,theoryId:59,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A soup has 12 g salt dissolved in 2 L. If it reduces to 1 L without losing salt, how many g of salt remain?`,ua:`У 2 л супу розчинено 12 г солі. Якщо він увариться до 1 л без втрати солі, скільки грамів солі залишиться?`},explanation:{en:`Water loss increases concentration but does not remove the original 12 g salt.`,ua:`Втрата води збільшує концентрацію, але не забирає початкові 12 г солі.`},numericInput:{unit:`g`,allowDecimals:!1,unitLabel:{en:`grams`,ua:`грамів`}},answer:{value:12,tolerance:0,unit:`g`}},{id:`cooking-059-05`,theoryId:59,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`You use already salty stock and will reduce the sauce by half. When is final salting best?`,ua:`Ви використовуєте вже солоний бульйон і зменшите об’єм соусу вдвічі. Коли краще остаточно солити?`},explanation:{en:`Salt concentration rises as water evaporates, so adjust near the end.`,ua:`Під час випаровування концентрація солі зростає, тому остаточно коригуйте наприкінці.`},options:[{id:`a`,text:{en:`Only after tasting the reduced sauce`,ua:`Лише після дегустації увареного соусу`}},{id:`b`,text:{en:`Add twice the usual salt before reduction`,ua:`Додати вдвічі більше солі до уварювання`}},{id:`c`,text:{en:`Never taste at any stage`,ua:`Ніколи не куштувати`}}],answer:{optionIds:[`a`]}},{id:`cooking-059-06`,theoryId:59,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which practices can improve salt management in recipes?`,ua:`Які дії допомагають керувати кількістю солі в рецептах?`},explanation:{en:`Salt concentration and bulk density vary by method and ingredients.`,ua:`Концентрація солі та насипна густина залежать від методу й інгредієнтів.`},options:[{id:`a`,text:{en:`Weigh salt for reproducibility`,ua:`Зважувати сіль для відтворюваності`}},{id:`b`,text:{en:`Taste after reducing salted stock`,ua:`Куштувати після уварювання солоного бульйону`}},{id:`c`,text:{en:`Account for salty cheese or miso additions`,ua:`Враховувати сіль у сирі чи місо`}},{id:`d`,text:{en:`Assume all salt types weigh the same per teaspoon`,ua:`Вважати, що всі види солі мають однакову масу в чайній ложці`}}],answer:{optionIds:[`a`,`b`,`c`]}}];var n={theoryId:59,exercises:i};export{n as default,i as exercises,a as theoryId};